#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTerminalScreen: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = TerminalScreen

    public static func lift(_ handle: UInt64) throws -> TerminalScreen {
        return TerminalScreen(unsafeFromHandle: handle)
    }

    public static func lower(_ value: TerminalScreen) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TerminalScreen {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: TerminalScreen, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTerminalScreen_lift(_ handle: UInt64) throws -> TerminalScreen {
    return try FfiConverterTypeTerminalScreen.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTerminalScreen_lower(_ value: TerminalScreen) -> UInt64 {
    return FfiConverterTypeTerminalScreen.lower(value)
}






/**
 * The library's entry point: local vault, server and SSH engine.
 *
 * Create it once when the app starts and share it. It is safe to use from
 * several threads.
 */
public protocol TermoakCoreProtocol: AnyObject, Sendable {
    
    /**
     * Adds a server user by email (team admins; only the owner can appoint
     * admins). Returns the updated members.
     */
    func addTeamMember(teamId: String, email: String, role: TeamRole) async throws  -> [TeamMember]
    
    /**
     * Audit log of the whole server, newest first (`before` = id to
     * paginate).
     */
    func adminAudit(before: Int64?, limit: UInt32) async throws  -> [AuditEvent]
    
    /**
     * Creates an invitation to sign up even when registration is closed.
     * `expires_in_hours`: 7 days if `None`, no expiry if 0.
     */
    func adminCreateInvite(email: String?, teamId: String?, isAdmin: Bool, expiresInHours: Int64?) async throws  -> CreatedAccountInvite
    
    /**
     * Creates a user directly (without an invitation).
     */
    func adminCreateUser(email: String, name: String, password: String, isAdmin: Bool) async throws  -> ServerUser
    
    /**
     * Created invitations.
     */
    func adminListInvites() async throws  -> [AccountInvite]
    
    /**
     * The server's users.
     */
    func adminListUsers() async throws  -> [ServerUser]
    
    /**
     * Sets a new password for a user and signs them out everywhere.
     */
    func adminResetPassword(userId: String, password: String) async throws 
    
    /**
     * Removes a user's two-factor authentication (they lost their phone and
     * recovery codes).
     */
    func adminResetTwoFactor(userId: String) async throws 
    
    /**
     * Revokes an unused invitation.
     */
    func adminRevokeInvite(inviteId: String) async throws 
    
    /**
     * Changes the name, the admin role or whether the account is disabled
     * (`None` = unchanged). Disabling signs the user out everywhere.
     */
    func adminUpdateUser(userId: String, name: String?, isAdmin: Bool?, disabled: Bool?) async throws  -> ServerUser
    
    /**
     * Creates a team (you will be its owner).
     */
    func createTeam(name: String) async throws  -> Team
    
    /**
     * The signed-in user, including their preferred language (`locale`).
     */
    func currentUser() async throws  -> ServerUser
    
    /**
     * Deletes a team (owners). Sessions shared with it are revoked.
     */
    func deleteTeam(teamId: String) async throws 
    
    /**
     * Disables two-factor authentication (requires the password and a current
     * or recovery code).
     */
    func disableTwoFactor(password: String, code: String) async throws 
    
    /**
     * Enables two-factor authentication with a code from the authenticator
     * app. Returns the (single-use) recovery codes: show them once so the
     * user can save them.
     */
    func enableTwoFactor(code: String) async throws  -> [String]
    
    /**
     * Leaves a team (the last owner cannot leave: appoint another owner or
     * delete the team first).
     */
    func leaveTeam(teamId: String) async throws 
    
    /**
     * The invitations of one of your sessions (also revoked and expired ones).
     */
    func listServerSessionShares(sessionId: String) async throws  -> [SessionShareInfo]
    
    /**
     * Members of a team.
     */
    func listTeamMembers(teamId: String) async throws  -> [TeamMember]
    
    /**
     * Teams you belong to (all of them, if you are an admin).
     */
    func listTeams() async throws  -> [Team]
    
    /**
     * Enables notifications on this device with the token the system gives
     * (on iOS, the `deviceToken` in hex; on Android, the Firebase token).
     * `sandbox` = iOS app built for development. Returns whether the server
     * has that service configured. Call it every time the system gives a new
     * token.
     */
    func registerPushToken(platform: PushPlatform, token: String, sandbox: Bool) async throws  -> Bool
    
    /**
     * Removes a member (they immediately lose access to the sessions shared
     * with the team).
     */
    func removeTeamMember(teamId: String, userId: String) async throws 
    
    /**
     * Renames a team (team owners and admins).
     */
    func renameTeam(teamId: String, name: String) async throws  -> Team
    
    /**
     * Revokes an invitation to a persistent session (whoever used it and
     * has no other one leaves).
     */
    func revokeServerSessionShare(sessionId: String, shareId: String) async throws 
    
    /**
     * Sends a test notification to this device.
     */
    func sendTestPush() async throws 
    
    /**
     * Saves the preferred language (BCP 47: `en`, `es`...) in the account,
     * so the server sends emails in it. Call it when the user picks a
     * language in the app (and after signing in, with the app's language).
     * Fails if the server does not have that language (see
     * [`server_locales`](crate::server_locales)). Returns the updated user.
     */
    func setLocale(locale: String) async throws  -> ServerUser
    
    /**
     * Changes a member's role. Returns the updated members.
     */
    func setTeamMemberRole(teamId: String, userId: String, role: TeamRole) async throws  -> [TeamMember]
    
    /**
     * Starts setting up two-factor authentication (generates a new secret; it
     * is not enabled until `enable_two_factor`).
     */
    func setupTwoFactor() async throws  -> TwoFactorSetup
    
    /**
     * Shares a persistent server session with a user, a team or through a
     * link (`control` = can ask for the keyboard; links wait for your
     * approval).
     */
    func shareServerSession(sessionId: String, target: ShareTarget, control: Bool, expiresInMinutes: Int64?) async throws  -> ShareInvite
    
    /**
     * Shares a session with every option (waiting room, automatic
     * keyboard...).
     */
    func shareServerSessionWith(sessionId: String, target: ShareTarget, options: ShareOptions) async throws  -> ShareInvite
    
    /**
     * Stops sharing a session: every invitation is revoked and everyone but
     * you leaves. Returns how many invitations were active.
     */
    func stopSharingServerSession(sessionId: String) async throws  -> UInt32
    
    /**
     * Two-factor authentication status.
     */
    func twoFactorStatus() async throws  -> TwoFactorStatus
    
    /**
     * Stops receiving notifications on this device.
     */
    func unregisterPushToken() async throws 
    
    /**
     * Changes an invitation live: whoever uses it gets the new permission
     * at once (going down to view only takes the keyboard away).
     */
    func updateServerSessionShare(sessionId: String, shareId: String, changes: ShareChanges) async throws  -> SessionShareInfo
    
    /**
     * One account: its sync, API, server sessions, AI, events and vaults.
     */
    func account(accountId: String) throws  -> AccountHandle
    
    /**
     * The account shown (`None`: all of them).
     */
    func accountView()  -> String?
    
    /**
     * The accounts on this device, in order.
     */
    func accounts()  -> [AccountInfo]
    
    /**
     * The current account (the one of the view; in the "all accounts"
     * view, the first active one).
     */
    func currentAccount()  -> AccountInfo?
    
    /**
     * Emails a new verification code to an account.
     */
    func resendAccountCode(accountId: String) async throws 
    
    /**
     * Shows one account (`Some`) or every account together (`None`). No
     * network needed; saved for the next start.
     */
    func setAccountView(accountId: String?) throws 
    
    /**
     * Syncs an account shortly after its items change on this device, and
     * when its server announces changes (off by default).
     */
    func setAutoSync(enabled: Bool) 
    
    /**
     * Signs in (adds the account, or signs the same account in again) and
     * makes it current. With two-factor authentication and no code it
     * fails with `TotpRequired`. Then sync it (`account(id).sync_now()`).
     */
    func signIn(server: ServerChoice, email: String, password: String, totpCode: String?) async throws  -> AccountInfo
    
    /**
     * Signs out of one account and deletes its data on this device (other
     * accounts and This-device items stay). Unregister the push token on
     * that server first. With unsynced changes and `discard_unsynced =
     * false`, nothing happens: see [`SignOutReport::signed_out`].
     */
    func signOutAccount(accountId: String, discardUnsynced: Bool) async throws  -> SignOutReport
    
    /**
     * Creates an account (official server, or your own with open
     * registration or an invitation). If the server verifies emails, the
     * account is `Unverified` until `verify_account`.
     *
     * `accept_terms`: the person ticked "I accept the terms of use and the
     * privacy policy" (`terms_url`/`privacy_url` from `server_info`); the
     * server records it, with `terms_version` if the app knows it.
     */
    func signUp(server: ServerChoice, email: String, name: String, password: String, invite: String?, acceptTerms: Bool, termsVersion: String?) async throws  -> AccountInfo
    
    /**
     * Moves or copies items (all from the same place) to an account's vault
     * (`target_account` + `target_vault`, default: its personal vault) or
     * to This device (`target_account = None`). Inside one account it is
     * an online operation; between This device and an account, or across
     * accounts, it happens here and syncs. `dry_run` returns the plan.
     */
    func transfer(items: [ItemRef], targetAccount: String?, targetVault: String?, mode: TransferMode, dryRun: Bool) async throws  -> TransferResult
    
    /**
     * Changes not uploaded yet of an account.
     */
    func unsyncedChanges(accountId: String) throws  -> UnsyncedChanges
    
    /**
     * The vaults of the accounts of `filter` (default: the current view),
     * as of their last sync.
     */
    func vaults(filter: ItemFilter?) throws  -> [VaultInfo]
    
    /**
     * Verifies an account's email with the six-digit code.
     */
    func verifyAccount(accountId: String, code: String, totpCode: String?) async throws  -> AccountInfo
    
    /**
     * Clears the command history of a host (or all of it if `None`).
     */
    func clearCommandHistory(hostId: String?) throws 
    
    /**
     * Command history to show in a list: the host's first and, if there are
     * not enough, the other hosts', by usage and recency. `query` filters by
     * content (case-insensitive; empty = all).
     */
    func commandHistory(hostId: String?, query: String, limit: UInt32) throws  -> [CommandHistoryItem]
    
    /**
     * Suggestions to complete `line` (what was typed after the prompt) in a
     * terminal of `host_id`. `os` is the host's operating system
     * (`SshHost.os`), to suggest the right package manager. Fast: it can be
     * called on every keystroke.
     */
    func completeCommand(hostId: String?, os: String?, line: String, limit: UInt32) throws  -> [CommandSuggestion]
    
    /**
     * Imports the contents of an `ssh_config` (the user picks it with the
     * file picker). Hosts whose name already exists are skipped, so it can
     * be repeated. Keys (`IdentityFile`) are only imported if the path
     * exists on this device; otherwise a warning is reported.
     */
    func importSshConfig(text: String, options: SshConfigImportOptions) throws  -> SshConfigImportReport
    
    /**
     * Imports an `ssh_config` from a path on the device (following its
     * `Include`s).
     */
    func importSshConfigFile(path: String, options: SshConfigImportOptions) throws  -> SshConfigImportReport
    
    /**
     * Saves an executed command (on Enter) in the host's history. It only
     * lives on this device, and commands that look like they contain secrets
     * or start with a space are not saved. Returns whether it was saved.
     */
    func recordCommand(hostId: String, command: String) throws  -> Bool
    
    /**
     * Downloads the recording (asciicast v2, `.cast`) of a server session to
     * `local_path`. Returns the number of bytes.
     */
    func downloadRecording(sessionId: String, localPath: String, listener: TransferListener?) async throws  -> UInt64
    
    /**
     * Deletes a remote file or directory (`recursive` for non-empty
     * directories).
     */
    func serverSftpDelete(hostId: String, path: String, recursive: Bool, accountId: String?) async throws 
    
    /**
     * Downloads a remote file to `local_path` (streamed; while in progress it
     * is written to `local_path.part`). Returns the number of bytes.
     */
    func serverSftpDownload(hostId: String, remotePath: String, localPath: String, listener: TransferListener?, accountId: String?) async throws  -> UInt64
    
    /**
     * The user's home directory on a host, over SFTP from the server.
     */
    func serverSftpHome(hostId: String, accountId: String?) async throws  -> String
    
    /**
     * Lists a directory over SFTP from the server.
     */
    func serverSftpList(hostId: String, path: String, accountId: String?) async throws  -> [RemoteFile]
    
    /**
     * Creates a remote directory (`parents` = also the intermediate ones).
     */
    func serverSftpMkdir(hostId: String, path: String, parents: Bool, accountId: String?) async throws 
    
    /**
     * Renames or moves a remote file.
     */
    func serverSftpRename(hostId: String, from: String, to: String, accountId: String?) async throws 
    
    /**
     * Uploads a local file to `remote_path` (replacing it if it exists).
     * Returns the number of bytes.
     */
    func serverSftpUpload(hostId: String, localPath: String, remotePath: String, listener: TransferListener?, accountId: String?) async throws  -> UInt64
    
    /**
     * Saves a previewed import. The target may differ from the preview's:
     * duplicates are found again against it.
     */
    func applyImport(preview: ImportPreview, options: ImportOptions) async throws  -> ImportSummary
    
    /**
     * Writes an export of a vault (or This device, or one group). Secrets
     * only go into a Termoak JSON, with `include_secrets` and a passphrase
     * of at least 8 characters (sealing takes a moment). `app` names the
     * app in the file ("Termoak for iOS 0.6.1").
     */
    func exportHosts(format: ExportFormat, scope: ExportScope, includeSecrets: Bool, passphrase: String?, app: String?) async throws  -> ExportResult
    
    /**
     * Reads a file for the import preview, against the vault it would go
     * to (`account_id` / `vault_id`, default the current account's
     * personal vault; `device_only`: This device) to find duplicates.
     * `file_name` helps guess the format. Fails with `Invalid` when the
     * file cannot be read as that format (an `ssh_config` too: use
     * `import_ssh_config`).
     */
    func previewImport(data: Data, fileName: String, format: ImportFormat?, accountId: String?, vaultId: String?, deviceOnly: Bool) async throws  -> ImportPreview
    
    /**
     * [`Self::preview_import`] of a file on the device.
     */
    func previewImportFile(path: String, format: ImportFormat?, accountId: String?, vaultId: String?, deviceOnly: Bool) async throws  -> ImportPreview
    
    /**
     * Checks whether hosts answer, at most `concurrency` at a time (0: 8),
     * each within 5 seconds, and answers in the order given. Hosts behind
     * jump hosts, of Strict vaults or with a proxy whose password cannot be
     * read are skipped; `off` are ids of hosts the user turned the check
     * off for.
     */
    func probeHosts(hosts: [ItemRef], off: [String], concurrency: UInt32) async throws  -> [HostProbe]
    
    /**
     * Attaches to a server session (yours or shared with you). `Hello`
     * arrives first, then the history.
     */
    func attachServerSession(sessionId: String, listener: ServerTerminalListener) async throws  -> ServerTerminalHandle
    
    /**
     * Joins with a link of this server while signed in (you appear with
     * your account's name; a direct invitation of yours is used if it
     * gives more).
     */
    func joinLink(token: String, listener: ServerTerminalListener) async throws  -> ServerTerminalHandle
    
    /**
     * Shares a local terminal through the server with the given title. Then
     * invite with `invite_user` or `invite_link`. SSH and Telnet terminals.
     */
    func shareTerminal(terminal: TerminalHandle, title: String) async throws  -> SharedTerminal
    
    /**
     * Subscribes to your account's events (WebSocket `/api/v1/events/ws`).
     * While the app is in the foreground it works as "push notifications".
     */
    func subscribeEvents(listener: ServerEventListener) async throws  -> EventSubscription
    
    /**
     * Your AI situation: own keys, whether your plan includes the server's
     * AI, its credit and this month's spending.
     */
    func aiAccess() async throws  -> AiAccessInfo
    
    func apiDelete(path: String) async throws  -> String
    
    func apiGet(path: String) async throws  -> String
    
    func apiPatch(path: String, bodyJson: String?) async throws  -> String
    
    func apiPost(path: String, bodyJson: String?) async throws  -> String
    
    func apiPut(path: String, bodyJson: String?) async throws  -> String
    
    /**
     * Authenticated request to any JSON endpoint of the server. `path` starts
     * with `/api/` (it may include a query), `body_json` is the JSON body (or
     * `nil`). Returns the response as JSON (`null` if it was empty).
     */
    func apiRequest(method: HttpMethod, path: String, bodyJson: String?) async throws  -> String
    
    func cancelAiTask(taskId: String) async throws 
    
    /**
     * Closes a server session (owner only).
     */
    func closeServerSession(sessionId: String) async throws 
    
    /**
     * Creates an AI task that runs on the server even if you close the app.
     * Actions that change something wait for your approval (`Ask` mode): they
     * show up in `pending_approvals` and on the events WebSocket.
     */
    func createAiTask(request: AiTaskRequest) async throws  -> AiTask
    
    /**
     * Approves or denies an action. `always` also approves the task's next
     * actions (switches to autonomous mode).
     */
    func decideApproval(taskId: String, approvalId: String, approve: Bool, always: Bool) async throws 
    
    /**
     * Deletes your own API key for a provider. `false` if there was none.
     */
    func deleteAiKey(provider: String) async throws  -> Bool
    
    /**
     * Current device name.
     */
    func deviceName() throws  -> String
    
    /**
     * A task with its full conversation (in `raw_json`).
     */
    func getAiTask(taskId: String) async throws  -> AiTask
    
    /**
     * State of a live session.
     */
    func getServerSession(sessionId: String) async throws  -> ServerSession
    
    /**
     * Whether the current account is signed in (with saved tokens).
     */
    func isLoggedIn() async throws  -> Bool
    
    /**
     * Your own AI API keys (without the keys).
     */
    func listAiKeys() async throws  -> [AiKeyInfo]
    
    /**
     * AI tasks, newest first.
     */
    func listAiTasks(limit: UInt32) async throws  -> [AiTask]
    
    /**
     * AI actions pending approval (from all tasks).
     */
    func listPendingApprovals() async throws  -> [AiApproval]
    
    /**
     * Your open sessions, sessions shared with you, and history.
     */
    func listServerSessions() async throws  -> ServerSessionList
    
    /**
     * Signs in to a server and remembers it (the tokens are stored encrypted
