/**
 * The library's entry point: local vault, server and SSH engine.
 *
 * Create it once when the app starts and share it. It is safe to use from
 * several threads.
 */
open class TermoakCore: TermoakCoreProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_termoak_ffi_fn_clone_termoakcore(self.handle, $0) }
    }
    /**
     * Opens (or creates) the local vault in `data_dir` with the key
     * `vault_key_b64` (the one from [`generate_vault_key`], stored by the app
     * in the Keychain or the Keystore). Fails with `Vault` if the key does not
     * match the data.
     */
public convenience init(dataDir: String, vaultKeyB64: String)throws  {
    let handle =
        try rustCallWithError(FfiConverterTypeTermoakError_lift) {
        uniffiCallStatus in
    uniffi_termoak_ffi_fn_constructor_termoakcore_new(
        FfiConverterString.lower(dataDir),
        FfiConverterString.lower(vaultKeyB64),uniffiCallStatus
    )
}
    self.init(unsafeFromHandle: handle)
}

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_termoak_ffi_fn_free_termoakcore(handle, $0) }
    }

    

    
