#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTermoakCore: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = TermoakCore

    public static func lift(_ handle: UInt64) throws -> TermoakCore {
        return TermoakCore(unsafeFromHandle: handle)
    }

    public static func lower(_ value: TermoakCore) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TermoakCore {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: TermoakCore, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTermoakCore_lift(_ handle: UInt64) throws -> TermoakCore {
    return try FfiConverterTypeTermoakCore.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTermoakCore_lower(_ value: TermoakCore) -> UInt64 {
    return FfiConverterTypeTermoakCore.lower(value)
}






/**
 * Progress of an SFTP transfer.
 *
 * **Threads**: called from a background thread after each chunk (256 KiB);
 * it must return quickly.
 */
public protocol TransferListener: AnyObject, Sendable {
    
    func onProgress(transferred: UInt64, total: UInt64?) 
    
}
/**
 * Progress of an SFTP transfer.
 *
 * **Threads**: called from a background thread after each chunk (256 KiB);
 * it must return quickly.
 */
open class TransferListenerImpl: TransferListener, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_termoak_ffi_fn_clone_transferlistener(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_termoak_ffi_fn_free_transferlistener(handle, $0) }
    }

    

    
open func onProgress(transferred: UInt64, total: UInt64?)  {try! rustCall() {
        uniffiCallStatus in
    uniffi_termoak_ffi_fn_method_transferlistener_on_progress(
            self.uniffiCloneHandle(),
        FfiConverterUInt64.lower(transferred),
        FfiConverterOptionUInt64.lower(total),uniffiCallStatus
    )
}
}
    

    
}



// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceTransferListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceTransferListener = UniffiVTableCallbackInterfaceTransferListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeTransferListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface TransferListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTransferListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface TransferListener: handle missing in uniffiClone")
            }
        },
        onProgress: { (
            uniffiHandle: UInt64,
            transferred: UInt64,
            total: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeTransferListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onProgress(
                     transferred: try FfiConverterUInt64.lift(transferred),
                     total: try FfiConverterOptionUInt64.lift(total)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceTransferListener> = {
